int max_area(vector<int> heights) {
    int left = 0, right = (int)heights.size() - 1, best = 0;
    while (left < right) {
        best = max(best, min(heights[left], heights[right]) * (right - left));
        if (heights[left] < heights[right]) {
            ++left;
        } else {
            --right;
        }
    }
    return best;
}

